// subtitles.js — généré depuis paste.txt
// Les balises HTML présentes dans le texte sont conservées.
const SUBTITLES_FR_CH4 = [
{ start: 1.000, end: 3.978, text: 'Bienvenue dans le programme BRIDGE -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },

  { start: 3.979, end: 8.162, text: 'Nous arrivons au quatrième chapitre de cette conférence.' },
  { start: 8.282, end: 13.996, text: 'Ce chapitre concerne la production de <font color="#FFFF00">vidéos</font> de cours,' },
  { start: 14.116, end: 21.012, text: 'des vidéos <font color="#FFFF00">inclusives</font>, dans les formations données aux étudiants.' },
  { start: 21.132, end: 27.466, text: 'L\'approche <font color="#FFFF00">vidéo</font> permet de répondre à plusieurs besoins mentionnés' },
  { start: 27.586, end: 31.879, text: 'dans cette diapositive, et mentionnés sur la partie gauche,' },
  { start: 31.999, end: 37.666, text: 'et la partie droite est consacrée aux <font color="#FFFF00">handicaps</font> associés' },
  { start: 37.786, end: 41.816, text: 'ou à des besoins hors handicap, comme les absences.' },
  { start: 41.936, end: 45.316, text: 'L\'approche vidéo offre plusieurs solutions, dont' },
  { start: 45.436, end: 49.152, text: 'la plus reconnue est celle de rattraper le cours.' },
  { start: 49.272, end: 53.119, text: 'Elle permet aussi de revoir plusieurs fois le cours, ou' },
  { start: 53.239, end: 57.956, text: 'une partie seulement si celle-ci aborde une notion particulière.' },
  { start: 58.076, end: 64.322, text: 'La vidéo <font color="#FFFF00">sous-titrée</font> permet aussi d\'associer audio et lecture,' },
  { start: 64.442, end: 67.092, text: 'favorisant ainsi la mémorisation.' },
  { start: 67.212, end: 72.126, text: 'Elle offre aussi la possibilité de suivre le cours sans prise de notes,' },
  { start: 72.246, end: 78.276, text: 'de faire des pauses, de revenir en arrière pour visionner les séquences désirées.' },
  { start: 78.396, end: 85.026, text: 'À mes yeux, la valeur la plus importante est celle mentionnée en bas de cette diapositive.' },
  { start: 85.146, end: 93.326, text: 'Cela concerne la création de <font color="#FFFF00">sous-titres</font> et de <font color="#FFFF00">transcriptions</font>,' },
  { start: 93.446, end: 101.476, text: 'et la <font color="#FFFF00">description orale</font> de ce qui est montré, ce qui est aussi un point important.' },
  { start: 101.596, end: 109.779, text: 'La partie relative aux <font color="#FFFF00">handicaps</font> considérés est affichée à droite de cette diapositive.' },
  { start: 109.899, end: 119.216, text: 'Il y a bien sûr tout ce qui concerne la <font color="#FFFF00">dyslexie</font> et les <font color="#FFFF00">troubles cognitifs</font>.' },
  { start: 119.336, end: 123.366, text: 'La gestion des absences, quelle que soit la raison.' },
  { start: 123.486, end: 130.202, text: 'Elle gère aussi les difficultés liées aux <font color="#FFFF00">troubles de la mémoire</font>.' },
  { start: 130.322, end: 138.306, text: 'Les vidéos sont aussi très utiles pour les étudiants souffrant de <font color="#FFFF00">fatigue chronique</font>.' },
  { start: 138.426, end: 143.742, text: 'Ils peuvent mettre la vidéo en pause pour la poursuivre une fois reposés.' },
  { start: 143.862, end: 151.756, text: 'L\'approche est indispensable pour les <font color="#FFFF00">problèmes auditifs</font>, car avoir des sous-titres,' },
  { start: 151.876, end: 157.589, text: 's\'ils sont adaptables pour ceux qui ont des difficultés visuelles, permet de régler' },
  { start: 157.709, end: 165.359, text: 'les <font color="#FFFF00">problèmes auditifs</font> ou le visionnage du cours dans un environnement bruyant.' },
  { start: 165.479, end: 172.506, text: 'Il y a quelques années, ce genre de <font color="#FFFF00">montage</font> était difficile à réaliser,' },
  { start: 172.626, end: 177.672, text: 'et il n\'y avait pas ou peu de solutions, à part des salles spéciales avec' },
  { start: 177.792, end: 181.509, text: 'des caméras et tout autre moyen d\'enregistrement.' },
  { start: 181.629, end: 186.976, text: 'Aujourd\'hui, ce n\'est plus le cas. Il existe plusieurs méthodes.' },
  { start: 187.096, end: 189.142, text: 'Je vais en présenter trois :' },
  { start: 189.262, end: 195.776, text: 'la plus simple est appelée l\'approche « <font color="#FFFF00">Influenceur</font> », qui utilise' },
  { start: 195.896, end: 200.009, text: 'un smartphone avec un trépied pour éviter les tremblements,' },
  { start: 200.129, end: 204.779, text: 'un micro ou un micro-cravate. L\'enseignant enregistre son cours' },
  { start: 204.899, end: 209.816, text: 'directement sur une tablette ou devant une projection de son cours.' },
  { start: 209.936, end: 216.386, text: 'La seconde approche est l\'utilisation du logiciel <font color="#FFFF00">PowerPoint</font>.' },
  { start: 216.506, end: 217.406, text: '' },
  { start: 217.526, end: 224.332, text: 'En plus de PowerPoint, il faut un micro-cravate ou un micro, pour enregistrer le son du cours,' },
  { start: 224.452, end: 227.319, text: 'synchronisé sur le déroulé des diapositives' },
  { start: 227.439, end: 229.422, text: 'ou des vidéos de cours.' },
  { start: 229.542, end: 236.459, text: 'Le logiciel peut ensuite exporter les diapositives synchronisées avec le son au format vidéo MP4.' },
  { start: 236.579, end: 241.379, text: 'Vous trouverez sur YouTube plusieurs tutoriels pour la fabrication de ce' },
  { start: 241.499, end: 245.349, text: 'format de cours <font color="#FFFF00">vidéo</font>.' },
  { start: 245.469, end: 251.076, text: 'Enfin, notre troisième méthode, celle que j\'utilise actuellement, consiste à' },
  { start: 251.196, end: 257.776, text: 'utiliser un logiciel de réunion à distance : l\'approche « <font color="#FFFF00">Meeting</font> »' },
  { start: 257.896, end: 260.409, text: 'permet l\'enregistrement de l\'écran,' },
  { start: 260.529, end: 264.022, text: 'd\'enregistrer la voix et, si vous le souhaitez,' },
  { start: 264.142, end: 268.859, text: 'd\'enregistrer l\'intervenant à travers la caméra de l\'ordinateur.' },
  { start: 268.979, end: 275.762, text: 'Ces logiciels permettent aussi de faire la <font color="#FFFF00">transcription</font> du cours.' },
  { start: 275.882, end: 280.332, text: 'Il sera retranscrit pour pouvoir être consulté par la suite.' },
  { start: 280.452, end: 285.919, text: 'Cette méthode « Meeting » est une procédure intéressante pour tous les enseignants' },
  { start: 286.039, end: 290.556, text: 'qui ont des difficultés à maîtriser les logiciels de montage.' },
  { start: 290.676, end: 294.639, text: 'À la fin de la réunion, le montage est utilisable.' },
  { start: 294.759, end: 300.006, text: 'Il n\'est pas toujours d\'une grande qualité, mais il constitue un premier jet' },
  { start: 300.126, end: 302.999, text: 'avec la vidéo, l\'audio, les images,' },
  { start: 303.119, end: 309.436, text: 'qui permettent de faire avancer une démarche d\'<font color="#FFFF00">inclusivité</font>.' },
  { start: 309.556, end: 313.602, text: 'Néanmoins, il y a 4 règles à respecter pour que ces vidéos' },
  { start: 313.722, end: 318.106, text: 'soient réellement <font color="#FFFF00">accessibles</font>.' },
  { start: 318.226, end: 324.676, text: 'La première est d\'avoir un <font color="#FFFF00">son</font> clair et parfaitement audible.' },
  { start: 324.796, end: 330.626, text: 'On dit : <i>« Un bon son est prioritaire par rapport à une bonne caméra. »</i>' },
  { start: 330.746, end: 334.859, text: 'Très souvent, pour corriger les défauts d\'enregistrement et' },
  { start: 334.979, end: 336.692, text: 'de mauvaise expression,' },
  { start: 336.812, end: 344.262, text: 'il est préférable de substituer sa voix et d\'utiliser une <font color="#FFFF00">voix artificielle</font>.' },
  { start: 344.382, end: 349.982, text: 'Ces méthodes « <font color="#FFFF00">Text To Voice</font> » donnent 5 % de mauvaises' },
  { start: 350.102, end: 355.512, text: 'transcriptions. Mais pour le reste, la voix est beaucoup plus claire,' },
  { start: 355.632, end: 360.796, text: 'standardisée, et parfois meilleure que l\'élocution de l\'intervenant.' },
  { start: 360.916, end: 365.829, text: 'Ensuite, il faut mettre à disposition des personnes ayant des problèmes' },
  { start: 365.949, end: 370.262, text: 'auditifs des <font color="#FFFF00">sous-titres</font>, dont la' },
  { start: 370.382, end: 373.566, text: 'taille doit varier en fonction du besoin.' },
  { start: 373.686, end: 378.669, text: 'Le sous-titre est corrigé pour être une version simplifiée du texte.' },
  { start: 378.789, end: 382.836, text: 'Ce n\'est pas simplement une transcription automatique, qui' },
  { start: 382.956, end: 385.806, text: 'peut se faire de façon indépendante.' },
  { start: 385.926, end: 390.506, text: 'Le sous-titre doit avoir un bon contraste et la taille qu\'il faut,' },
  { start: 390.626, end: 394.276, text: 'pour les personnes ayant des problèmes auditifs.' },
  { start: 394.396, end: 399.796, text: 'Le troisième point est important et indispensable pour les cours scientifiques et' },
  { start: 399.916, end: 403.079, text: 'techniques, comme la chimie organique.' },
  { start: 403.199, end: 407.916, text: 'Nous devons décrire oralement ce qui est visuellement important.' },
  { start: 408.036, end: 411.952, text: 'C\'est la troisième case en bas que je vous présente.' },
  { start: 412.072, end: 419.122, text: 'Cela permet de renforcer l\'approche <font color="#FFFF00">sous-titrage</font> présentée auparavant.' },
  { start: 419.242, end: 425.909, text: 'L\'approche de <font color="#FFFF00">description de l\'image</font> est essentielle dans des cas comme' },
  { start: 426.029, end: 427.742, text: 'la chimie organique, où' },
  { start: 427.862, end: 432.379, text: 'il faut prendre son temps pour décrire une réaction chimique.' },
  { start: 432.499, end: 435.792, text: 'Les réactifs initiaux, les composés obtenus,' },
  { start: 435.912, end: 441.102, text: 'les conditions opératoires, les catalyseurs, les solvants, etc.' },
  { start: 441.222, end: 442.156, text: 'On ne peut pas' },
  { start: 442.276, end: 446.189, text: 'se contenter d\'une image du parcours réactionnel, car on' },
  { start: 446.309, end: 449.092, text: 'perdra immédiatement les étudiants.' },
  { start: 449.212, end: 450.879, text: 'Il faut décrire oralement' },
  { start: 450.999, end: 453.716, text: 'tout le processus chimique engagé.' },
  { start: 453.836, end: 456.816, text: 'Ceci est vrai dans de nombreuses sciences,' },
  { start: 456.936, end: 463.052, text: 'où il est nécessaire de décrire clairement et oralement ce que nous voyons à l\'écran.' },
  { start: 463.172, end: 465.932, text: 'Le quatrième point, en bas à droite,' },
  { start: 466.052, end: 468.969, text: 'concerne la durée de la présentation.' },
  { start: 469.089, end: 475.272, text: 'Il est d\'usage que cette présentation ne dépasse pas 25 minutes par notion importante.' },
  { start: 475.392, end: 480.109, text: 'Nous pouvons aller au-delà s\'il s\'agit d\'une partie descriptive.' },
  { start: 480.229, end: 484.972, text: 'Sinon, pour une notion importante, 20 minutes est la cible.' },
  { start: 485.092, end: 490.339, text: 'Cela évite de perdre les étudiants, et surtout ceux qui ont des problèmes de' },
  { start: 490.459, end: 496.242, text: 'mémorisation ou qui souffrent de <font color="#FFFF00">fatigue cognitive</font>.' },
  { start: 496.362, end: 502.212, text: 'Il n\'est plus nécessaire d\'avoir un studio d\'enregistrement pour faire ses cours.' },
  { start: 502.332, end: 507.892, text: 'Il suffit d\'avoir quelques logiciels, et les logiciels que j\'ai présentés ici,' },
  { start: 508.012, end: 513.976, text: 'sont tous <font color="#FFFF00">open source</font>, à l\'exception de PowerPoint.' },
  { start: 514.096, end: 518.409, text: 'Ils fonctionnent avec plusieurs systèmes d\'exploitation, comme' },
  { start: 518.529, end: 520.826, text: 'Linux, Windows ou Mac OS.' },
  { start: 520.946, end: 524.972, text: 'Pour l\'enregistrement, vous pouvez utiliser PowerPoint,' },
  { start: 525.092, end: 530.359, text: 'associé à <font color="#FFFF00">Subtitle Edit</font> pour faire des sous-titres' },
  { start: 530.479, end: 532.796, text: 'et d\'autres fonctionnalités.' },
  { start: 532.916, end: 539.522, text: 'Si vous avez des images, des diapositives, des extraits de film, ou tout autre élément pour' },
  { start: 539.642, end: 548.872, text: 'faire le cours, on peut aussi enregistrer la vidéo finale avec un logiciel qui s\'appelle <font color="#FFFF00">OBS Studio</font>.' },
  { start: 548.992, end: 554.439, text: 'Ce logiciel open source fait les mêmes opérations que les logiciels de réunion,' },
  { start: 554.559, end: 556.692, text: 'il permet d\'enregistrer le cours' },
  { start: 556.812, end: 559.729, text: 'selon un montage que vous choisissez.' },
  { start: 559.849, end: 567.192, text: 'Le <font color="#FFFF00">montage</font> est nécessaire pour couper, assembler, chapitrer le cours.' },
  { start: 567.312, end: 571.692, text: 'Il existe pour cela plusieurs logiciels de montage open source,' },
  { start: 571.812, end: 575.572, text: 'dont celui fourni par KDE, Non Linear Video Editor,' },
  { start: 575.692, end: 579.406, text: 'dit <font color="#FFFF00">Kdenlive</font>, qui permet' },
  { start: 579.526, end: 582.309, text: 'de faire le montage vidéo du cours.' },
  { start: 582.429, end: 588.609, text: 'Pour la <font color="#FFFF00">transcription</font> de l\'oral en texte, l\'une des solutions' },
  { start: 588.729, end: 595.406, text: 'reconnues, quelle que soit la langue utilisée, est <font color="#FFFF00">Whisper</font>.' },
  { start: 595.526, end: 599.306, text: 'Le logiciel que j\'utilise dans les formations, ou pour' },
  { start: 599.426, end: 607.032, text: 'les conférences, est <font color="#FFFF00">Subtitle Edit</font>, qui est un logiciel open source efficace,' },
  { start: 607.152, end: 614.112, text: 'compatible avec de nombreux systèmes d\'exploitation, et qui fait la transcription écrite de l\'oral,' },
  { start: 614.232, end: 619.482, text: 'permet de faire de l\'édition et de la traduction si cela est nécessaire.' },
  { start: 619.602, end: 626.299, text: 'Il fait appel à d\'autres logiciels, comme <font color="#FFFF00">Whisper</font> par exemple.' },
  { start: 626.419, end: 629.936, text: 'Il s\'occupe de le télécharger automatiquement.' },
  { start: 630.056, end: 634.836, text: 'Si vous voulez faire la traduction du français vers une autre langue,' },
  { start: 634.956, end: 639.072, text: 'il existe plusieurs logiciels open source sur Internet.' },
  { start: 639.192, end: 647.002, text: 'Ici, j\'ai cité <font color="#FFFF00">Argos Translate</font>, mais cela peut être n\'importe quel logiciel.' },
  { start: 647.122, end: 652.569, text: 'Pour ce qui est du nettoyage audio, si vous souhaitez continuer avec votre voix' },
  { start: 652.689, end: 659.516, text: 'ou avec un son non numérique, <font color="#FFFF00">Audacity</font> est le logiciel pour filtrer,' },
  { start: 659.636, end: 663.129, text: 'réduire le bruit, augmenter le contraste audio,' },
  { start: 663.249, end: 666.766, text: 'et avoir ainsi un confort auditif remarquable.' },
  { start: 666.886, end: 672.912, text: 'Enfin, votre vidéo doit être mise dans un format compatible avec la diffusion finale,' },
  { start: 673.032, end: 675.416, text: 'comme MP4 ou AVI par exemple.' },
  { start: 675.536, end: 678.782, text: 'Il faut avoir un logiciel de conversion vidéo,' },
  { start: 678.902, end: 683.682, text: 'et je vous propose <font color="#FFFF00">FFmpeg</font>, qui permet de' },
  { start: 683.802, end: 687.919, text: 'faire toutes les transformations dont vous avez besoin.' },
  { start: 688.039, end: 692.732, text: 'Pour l\'approche « Meeting », à la place d\'OBS Studio par exemple,' },
  { start: 692.852, end: 701.259, text: 'je cite les quatre grands logiciels de réunion, comme <font color="#FFFF00">Zoom</font>, que j\'utilise pour ce format,' },
  { start: 701.379, end: 710.142, text: '<font color="#FFFF00">Microsoft Teams</font>, <font color="#FFFF00">WebEx</font> ou <font color="#FFFF00">FaceTime</font>.' },
  { start: 710.262, end: 713.379, text: 'Vous choisissez celui que vous préférez.' },
  { start: 713.499, end: 719.082, text: 'Voici ce qu\'il faut faire pratiquement. J\'ai pris un exemple parmi les sujets' },
  { start: 719.202, end: 726.142, text: '<font color="#FFFF00">BRIDGE</font>, dont le projet est de donner, sous une forme numérique, une' },
  { start: 726.262, end: 732.442, text: 'formation issue de thématiques de recherche, d\'où le nom de <i>« Bridging Research and</i>' },
  { start: 732.562, end: 740.456, text: '<i>Inclusive Digital Education »</i>, sur les 8 formations de <font color="#FFFF00">SciencExpert</font>, qui sont' },
  { start: 740.576, end: 748.869, text: 'les <font color="#FFFF00">Colloïdes</font>, le <font color="#FFFF00">Vieillissement et Durabilité des matériaux</font>,' },
  { start: 748.989, end: 756.016, text: 'l\'<font color="#FFFF00">Initiation aux Polymères</font>, les <font color="#FFFF00">Silicones</font>,' },
  { start: 756.136, end: 763.229, text: 'la <font color="#FFFF00">Formulation et la Plasturgie</font>, les <font color="#FFFF00">Latex</font>,' },
  { start: 763.349, end: 768.379, text: 'et enfin, les <font color="#FFFF00">Colles et les Adhésifs</font>.' },
  { start: 768.499, end: 772.346, text: 'La première étape consiste à scénariser les formations,' },
  { start: 772.466, end: 776.249, text: 'c\'est-à-dire faire des blocs d\'environ 20 minutes.' },
  { start: 776.369, end: 782.549, text: 'Par exemple, le cours sur le Vieillissement et la Durabilité des polymères a été fragmenté' },
  { start: 782.669, end: 787.452, text: 'en 27 modules ayant 21 minutes en moyenne. Nous pouvons avoir des' },
  { start: 787.572, end: 792.022, text: 'modules demandant plus de temps s\'ils sont très descriptifs.' },
  { start: 792.142, end: 796.306, text: 'Sans pause, le cours initial est prévu pour 8 heures.' },
  { start: 796.426, end: 802.256, text: 'Sous sa forme <font color="#FFFF00">inclusive</font>, le cours fait 10 heures.' },
  { start: 802.376, end: 806.422, text: 'Retenons que l\'approche vidéo, par le passage d\'un cours à' },
  { start: 806.542, end: 811.639, text: 'une vidéo, demande de prévoir environ 20 % de temps supplémentaire.' },
  { start: 811.759, end: 814.606, text: 'Cela nous donne 27 modules à travailler,' },
  { start: 814.726, end: 820.106, text: 'avec l\'aide du logiciel <font color="#FFFF00">Subtitle Edit</font>, qui permet' },
  { start: 820.226, end: 826.076, text: 'd\'obtenir les <font color="#FFFF00">sous-titres</font>. Ils peuvent être traduits' },
  { start: 826.196, end: 829.892, text: 'dans la langue choisie, selon le besoin final.' },
  { start: 830.012, end: 838.596, text: 'Le dernier sujet qu\'il faut aborder pour ces vidéos concerne les <font color="#FFFF00">réglementations</font> à respecter.' },
  { start: 838.716, end: 842.499, text: 'Quels sont les droits et les devoirs à respecter ?' },
  { start: 842.619, end: 848.666, text: 'Les devoirs généraux sont bien entendu les <font color="#FFFF00">droits d\'auteur</font>,' },
  { start: 848.786, end: 854.416, text: 'pour les cours que vous utilisez, et aussi pour les documents illustratifs.' },
  { start: 854.536, end: 859.429, text: 'Le droit d\'auteur, ou à défaut le droit de citation, s\'applique pour' },
  { start: 859.549, end: 862.066, text: 'ces documents et leurs auteurs.' },
  { start: 862.186, end: 867.612, text: 'Si vous filmez un enseignant, vérifiez que vous possédez le droit à l\'image,' },
  { start: 867.732, end: 871.649, text: 'et aussi un droit d\'auteur s\'il est en train d\'agir.' },
  { start: 871.769, end: 877.576, text: 'Enfin, si vous enregistrez ou utilisez des images d\'étudiants, encore une fois,' },
  { start: 877.696, end: 882.429, text: 'vous devez respecter le <font color="#FFFF00">droit à l\'image</font> et' },
  { start: 882.549, end: 887.599, text: 'vérifier que vous êtes conforme au <font color="#FFFF00">RGPD</font>.' },
  { start: 887.719, end: 890.546, text: 'Néanmoins, lorsqu\'on crée des vidéos,' },
  { start: 890.666, end: 895.629, text: 'de nouveaux droits s\'appliquent, avec une attention particulière.' },
  { start: 895.749, end: 902.642, text: 'Le premier, qu\'on appelle le <font color="#FFFF00">droit du producteur</font>, est un droit voisin' },
  { start: 902.762, end: 907.969, text: 'du producteur, adapté aux vidéogrammes, parce que vous avez fragmenté,' },
  { start: 908.089, end: 910.756, text: 'séquencé et monté un ensemble d\'éléments' },
  { start: 910.876, end: 913.392, text: 'vidéo pour réaliser le montage.' },
  { start: 913.512, end: 918.229, text: 'Cela relève du <font color="#FFFF00">droit du producteur</font>.' },
  { start: 918.349, end: 922.376, text: 'Ensuite, il y a la réalisation, et vous avez encore une' },
  { start: 922.496, end: 930.079, text: 'fois des droits de création d\'une <font color="#FFFF00">œuvre audiovisuelle</font> qui doivent s\'appliquer.' },
  { start: 930.199, end: 934.066, text: 'Pour ceux qui sont dans le service public et qui répondent' },
  { start: 934.186, end: 937.166, text: 'aux lois sur le handicap et l\'inclusivité,' },
  { start: 937.286, end: 940.066, text: 'et qui relèvent du code de l\'éducation,' },
  { start: 940.186, end: 944.212, text: 'il est prévu que, pour cette mission de service public,' },
  { start: 944.332, end: 949.379, text: 'strictement nécessaire à l\'inclusion des étudiants, l\'ensemble des droits' },
  { start: 949.499, end: 953.079, text: 'd\'exploitation de l\'œuvre, produite par un agent de' },
  { start: 953.199, end: 956.762, text: 'l\'État, appartient obligatoirement à l\'État.' },
  { start: 956.882, end: 958.932, text: 'Donc vous êtes protégés.' },
  { start: 959.052, end: 964.766, text: 'Si vous n\'êtes pas dans le service public, si vous êtes dans une école sous contrat' },
  { start: 964.886, end: 968.132, text: 'ou une école hors contrat, vous devez vérifier' },
  { start: 968.252, end: 970.902, text: 'que ces droits sont bien établis.' },
  { start: 971.022, end: 976.536, text: 'Vous devez faire une demande pour disposer des droits d\'utilisation de la vidéo,' },
  { start: 976.656, end: 982.352, text: 'c\'est-à-dire du droit du producteur et de réalisation de l\'œuvre, en France.' },
  { start: 982.472, end: 985.052, text: 'Et en plus des quatre autres droits,' },
  { start: 985.172, end: 988.222, text: 'que je vous ai mentionnés initialement.' },

  { start: 988.22, end: 999.000, text: 'Merci pour votre attention. Allez au chapitre 5.' },


];

const SUBTITLES_EN_CH4 = [
{ start: 1.000, end: 3.978, text: 'Welcome to the BRIDGE programme -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },

 { start: 3.979, end: 7.379, text: 'We arrive at the fourth chapter of this conference.' },
  { start: 7.499, end: 12.531, text: 'This chapter concerns the production of <font color="#FFFF00">course videos</font>,' },
  { start: 12.651, end: 17.966, text: '<font color="#FFFF00">inclusive</font> videos, in the training given to students.' },
  { start: 18.086, end: 22.615, text: 'The <font color="#FFFF00">video</font> approach meets several needs mentioned' },
  { start: 22.735, end: 26.212, text: 'in this slide, and mentioned on the left part, and the' },
  { start: 26.332, end: 28.744, text: 'right part is devoted to associated <font' },
  { start: 28.864, end: 34.002, text: 'color="#FFFF00">disabilities</font> or to non-disability needs, like absences.' },
  { start: 34.122, end: 36.860, text: 'The video approach offers several solutions,' },
  { start: 36.980, end: 40.792, text: 'the most recognized of which is to catch up on the course.' },
  { start: 40.912, end: 44.238, text: 'It also allows you to review the course several times,' },
  { start: 44.358, end: 48.053, text: 'or only part of it if it addresses a particular concept.' },
  { start: 48.173, end: 53.852, text: 'The <font color="#FFFF00">subtitled video</font> also allows you to combine audio and reading,' },
  { start: 53.972, end: 56.019, text: 'thus promoting memorization.' },
  { start: 56.139, end: 60.760, text: 'It also offers the possibility of following the course without taking notes,' },
  { start: 60.880, end: 64.783, text: 'to take breaks, to go back to view the desired sequences.' },
  { start: 64.903, end: 70.217, text: 'To me, the most important value is the one mentioned at the bottom of this slide.' },
  { start: 70.337, end: 77.370, text: 'This concerns the creation of <font color="#FFFF00">subtitles</font> and <font color="#FFFF00">transcriptions</font>,' },
  { start: 77.490, end: 84.216, text: 'and the <font color="#FFFF00">oral description</font> of what is shown, which is also an important point.' },
  { start: 84.336, end: 91.442, text: 'The part relating to <font color="#FFFF00">disabilities</font> considered is displayed to the right of this slide.' },
  { start: 91.562, end: 99.785, text: 'There is of course everything relating to <font color="#FFFF00">dyslexia</font> and <font color="#FFFF00">cognitive disorders</font>.' },
  { start: 99.905, end: 102.808, text: 'Absence management, whatever the reason.' },
  { start: 102.928, end: 108.328, text: 'It also manages difficulties linked to <font color="#FFFF00">memory disorders</font>.' },
  { start: 108.448, end: 115.025, text: 'The videos are also very useful for students suffering from <font color="#FFFF00">chronic fatigue</font>.' },
  { start: 115.145, end: 118.427, text: 'They can pause the video to continue when rested.' },
  { start: 118.547, end: 124.050, text: 'The approach is essential for <font color="#FFFF00">hearing problems</font>, because having' },
  { start: 124.170, end: 129.941, text: 'subtitles, if they are adaptable for those who have visual difficulties, makes it possible to' },
  { start: 130.061, end: 136.284, text: 'resolve <font color="#FFFF00">hearing problems</font> or viewing the course in a noisy environment.' },
  { start: 136.404, end: 140.437, text: 'A few years ago, this kind of <font color="#FFFF00">editing</font>' },
  { start: 140.557, end: 143.648, text: 'was difficult to achieve, and there were few or no' },
  { start: 143.768, end: 149.141, text: 'solutions, apart from special rooms with cameras and any other means of recording.' },
  { start: 149.261, end: 153.800, text: 'Today, this is no longer the case. There are several methods.' },
  { start: 153.920, end: 156.893, text: 'I will present three: the simplest is called the' },
  { start: 157.013, end: 160.398, text: 'approach “<font color="#FFFF00">Influencer</font>”, who' },
  { start: 160.518, end: 163.668, text: 'uses a smartphone with a tripod to avoid shaking, a' },
  { start: 163.788, end: 167.483, text: 'microphone or a lavalier microphone. The teacher records' },
  { start: 167.603, end: 172.355, text: 'his lesson directly on a tablet or in front of a projection of his lesson.' },
  { start: 172.475, end: 177.758, text: 'The second approach is the use of <font color="#FFFF00">PowerPoint</font> software.' },
  { start: 177.878, end: 178.778, text: '' },
  { start: 178.898, end: 181.754, text: 'In addition to PowerPoint, you need a lavalier' },
  { start: 181.874, end: 184.874, text: 'microphone or microphone to record the audio of the' },
  { start: 184.994, end: 189.661, text: 'course, synchronized with the progress of the slides or course videos.' },
  { start: 189.781, end: 194.828, text: 'The software can then export the sound-synchronized slides to MP4 video format.' },
  { start: 194.948, end: 198.713, text: 'You will find several tutorials on YouTube for making this <font' },
  { start: 198.833, end: 201.763, text: 'color="#FFFF00">video</font> course format.' },
  { start: 201.883, end: 205.333, text: 'Finally, our third method, the one I currently use,' },
  { start: 205.453, end: 210.661, text: 'is to use remote meeting software: the “<font color="#FFFF00">Meeting</font>” approach' },
  { start: 210.781, end: 212.696, text: 'allows screen recording, voice' },
  { start: 212.816, end: 215.116, text: 'recording and, if you wish, record' },
  { start: 215.236, end: 217.989, text: 'the speaker through the computer camera.' },
  { start: 218.109, end: 224.215, text: 'These software also allow you to do the <font color="#FFFF00">transcription</font> of the course.' },
  { start: 224.335, end: 228.088, text: 'It will be transcribed so that it can be consulted later.' },
  { start: 228.208, end: 231.325, text: 'This “Meeting” method is an interesting procedure for' },
  { start: 231.445, end: 235.375, text: 'all teachers who have difficulty mastering editing software.' },
  { start: 235.495, end: 238.751, text: 'At the end of the meeting, the edit is usable.' },
  { start: 238.871, end: 243.994, text: 'It is not always of high quality, but it constitutes a first draft with the video,' },
  { start: 244.114, end: 245.238, text: 'audio, images,' },
  { start: 245.358, end: 250.581, text: 'which allow us to advance an approach of <font color="#FFFF00">inclusivity</font>.' },
  { start: 250.701, end: 252.969, text: 'However, there are 4 rules to follow' },
  { start: 253.089, end: 257.665, text: 'so that these videos are truly <font color="#FFFF00">accessible</font>.' },
  { start: 257.785, end: 263.244, text: 'The first is to have a clear and perfectly audible <font color="#FFFF00">sound</font>.' },
  { start: 263.364, end: 266.514, text: 'They say: <i>“Good sound takes priority over a good' },
  { start: 266.634, end: 270.361, text: 'camera. »</i> Very often, to correct recording defects' },
  { start: 270.481, end: 273.925, text: 'and poor expression, it is preferable to substitute your' },
  { start: 274.045, end: 278.151, text: 'voice and use an <font color="#FFFF00">artificial voice</font>.' },
  { start: 278.271, end: 282.388, text: 'These “<font color="#FFFF00">Text To Voice</font>” methods give 5% bad' },
  { start: 282.508, end: 286.738, text: 'transcriptions. But for the rest, the voice is much clearer,' },
  { start: 286.858, end: 291.114, text: 'standardized, and sometimes better than the speaker\'s delivery.' },
  { start: 291.234, end: 292.795, text: 'Then, we must make <font' },
  { start: 292.915, end: 295.563, text: 'color="#FFFF00">subtitles</font> available to' },
  { start: 295.683, end: 300.938, text: 'people with hearing problems, the size of which must vary depending on the need.' },
  { start: 301.058, end: 305.282, text: 'The subtitle is corrected to be a simplified version of the text.' },
  { start: 305.402, end: 308.140, text: 'It is not simply an automatic transcription,' },
  { start: 308.260, end: 310.543, text: 'which can be done independently.' },
  { start: 310.663, end: 313.721, text: 'The subtitle should have good contrast and the right' },
  { start: 313.841, end: 316.477, text: 'size for people with hearing problems.' },
  { start: 316.597, end: 320.655, text: 'The third point is important and essential for scientific courses and' },
  { start: 320.775, end: 323.561, text: 'techniques, such as organic chemistry.' },
  { start: 323.681, end: 327.375, text: 'We need to verbally describe what is visually important.' },
  { start: 327.495, end: 331.307, text: 'This is the third box at the bottom that I present to you.' },
  { start: 331.427, end: 337.121, text: 'This reinforces the <font color="#FFFF00">subtitling</font> approach presented previously.' },
  { start: 337.241, end: 340.182, text: 'The <font color="#FFFF00">image description</font>' },
  { start: 340.302, end: 343.628, text: 'approach is essential in cases like organic chemistry,' },
  { start: 343.748, end: 347.972, text: 'where you have to take your time to describe a chemical reaction.' },
  { start: 348.092, end: 351.039, text: 'The initial reagents, the compounds obtained,' },
  { start: 351.159, end: 355.480, text: 'the operating conditions, the catalysts, the solvents, etc.' },
  { start: 355.600, end: 357.364, text: 'We cannot be satisfied with an' },
  { start: 357.484, end: 359.693, text: 'image of the reaction path, because' },
  { start: 359.813, end: 362.448, text: 'we will immediately lose the students.' },
  { start: 362.568, end: 364.568, text: 'It is necessary to describe orally' },
  { start: 364.688, end: 367.206, text: 'the entire chemical process engaged.' },
  { start: 367.326, end: 369.241, text: 'This is true in many sciences,' },
  { start: 369.361, end: 374.408, text: 'where it is necessary to clearly and orally describe what we see on the screen.' },
  { start: 374.528, end: 377.063, text: 'The fourth point, at the bottom right,' },
  { start: 377.183, end: 380.054, text: 'concerns the duration of the presentation.' },
  { start: 380.174, end: 385.750, text: 'It is customary that this presentation does not exceed 25 minutes per important concept.' },
  { start: 385.870, end: 388.917, text: 'We can go beyond if it is a descriptive part.' },
  { start: 389.037, end: 393.384, text: 'Otherwise, for an important concept, 20 minutes is the target.' },
  { start: 393.504, end: 395.301, text: 'This avoids losing students,' },
  { start: 395.421, end: 402.527, text: 'especially those who have memorization problems or who suffer from <font color="#FFFF00">cognitive fatigue</font>.' },
  { start: 402.647, end: 407.106, text: 'It is no longer necessary to have a recording studio to take lessons.' },
  { start: 407.226, end: 414.291, text: 'You just need some software, and the software I\'ve presented here are all <font color="#FFFF00">open source</font>,' },
  { start: 414.411, end: 416.752, text: 'with the exception of PowerPoint.' },
  { start: 416.872, end: 419.493, text: 'They work with multiple operating systems,' },
  { start: 419.613, end: 421.927, text: 'like Linux, Windows or Mac OS.' },
  { start: 422.047, end: 424.583, text: 'For recording, you can use PowerPoint,' },
  { start: 424.703, end: 427.291, text: 'combined with <font color="#FFFF00">Subtitle' },
  { start: 427.411, end: 430.693, text: 'Edit</font> to make subtitles and other features.' },
  { start: 430.813, end: 434.734, text: 'If you have images, slides, film clips, or anything else to' },
  { start: 434.854, end: 441.992, text: 'do the course, you can also record the final video with software called <font color="#FFFF00">OBS Studio</font>.' },
  { start: 442.112, end: 444.406, text: 'This open source software does the same' },
  { start: 444.526, end: 447.323, text: 'operations as meeting software, it allows you' },
  { start: 447.443, end: 450.843, text: 'to record the course using an edit that you choose.' },
  { start: 450.963, end: 456.807, text: '<font color="#FFFF00">editing</font> is necessary to cut, assemble and chapter the course.' },
  { start: 456.927, end: 459.868, text: 'There are several open source editing software for' },
  { start: 459.988, end: 463.112, text: 'this, including that provided by KDE, Non Linear' },
  { start: 463.232, end: 465.029, text: 'Video Editor, known as <font' },
  { start: 465.149, end: 470.523, text: 'color="#FFFF00">Kdenlive</font>, which allows you to edit the video of the course.' },
  { start: 470.643, end: 475.851, text: 'For <font color="#FFFF00">transcription</font> of oral into text, one of the solutions' },
  { start: 475.971, end: 481.377, text: 'recognized, whatever the language used, is <font color="#FFFF00">Whisper</font>.' },
  { start: 481.497, end: 485.327, text: 'The software I use in training, or for conferences, is <font' },
  { start: 485.447, end: 489.597, text: 'color="#FFFF00">Subtitle Edit</font>, which is efficient open source' },
  { start: 489.717, end: 493.899, text: 'software, compatible with many operating systems, and who does the' },
  { start: 494.019, end: 499.216, text: 'written transcription of the oral, allows editing and translation if necessary.' },
  { start: 499.336, end: 504.474, text: 'It uses other software, like <font color="#FFFF00">Whisper</font> for example.' },
  { start: 504.594, end: 507.700, text: 'It takes care of downloading it automatically.' },
  { start: 507.820, end: 511.323, text: 'If you want to translate from French to another language,' },
  { start: 511.443, end: 515.078, text: 'There are several open source software on the Internet.' },
  { start: 515.198, end: 520.807, text: 'Here I cited <font color="#FFFF00">Argos Translate</font>, but it can be any software.' },
  { start: 520.927, end: 524.371, text: 'As for audio cleaning, if you want to continue with your' },
  { start: 524.491, end: 526.877, text: 'voice or with non-digital sound, <font' },
  { start: 526.997, end: 530.558, text: 'color="#FFFF00">Audacity</font> is the software to filter,' },
  { start: 530.678, end: 536.320, text: 'reduce noise, increase the audio contrast, and thus have remarkable hearing comfort.' },
  { start: 536.440, end: 541.445, text: 'Finally, your video must be put in a format compatible with the final broadcast,' },
  { start: 541.565, end: 543.789, text: 'such as MP4 or AVI for example.' },
  { start: 543.909, end: 546.588, text: 'You need to have video conversion software,' },
  { start: 546.708, end: 550.976, text: 'and I suggest <font color="#FFFF00">FFmpeg</font>, which allows you to' },
  { start: 551.096, end: 553.673, text: 'do whatever transformations you need.' },
  { start: 553.793, end: 559.504, text: 'For the “Meeting” approach, instead of OBS Studio for example, I cite the four major meeting' },
  { start: 559.624, end: 565.015, text: 'software, like <font color="#FFFF00">Zoom</font>, which I use for this format, <font' },
  { start: 565.135, end: 572.509, text: 'color="#FFFF00">Microsoft Teams</font>, <font color="#FFFF00">WebEx</font> or <font color="#FFFF00">FaceTime</font>.' },
  { start: 572.629, end: 574.794, text: 'You choose the one you prefer.' },
  { start: 574.914, end: 581.523, text: 'Here\'s what to do practically. I took an example from the <font color="#FFFF00">BRIDGE</font> subjects,' },
  { start: 581.643, end: 584.413, text: 'whose project is to give, in digital form,' },
  { start: 584.533, end: 589.507, text: 'training based on research themes, hence the name of <i>“Bridging Research and</i>' },
  { start: 589.627, end: 593.953, text: '<i>Inclusive Digital Education”</i>, on the 8 training courses of <font' },
  { start: 594.073, end: 599.726, text: 'color="#FFFF00">SciencExpert</font>, which are <font color="#FFFF00">Colloids</font>, <font' },
  { start: 599.846, end: 603.702, text: 'color="#FFFF00">Aging and Durability of materials</font>, <font' },
  { start: 603.822, end: 609.298, text: 'color="#FFFF00">Introduction to Polymers</font>, <font color="#FFFF00">Silicones</font>,' },
  { start: 609.418, end: 619.268, text: '<font color="#FFFF00">Formulation and Plastics</font>, <font color="#FFFF00">Latex</font>, and finally, <font color="#FFFF00">Glues and Adhesives</font>.' },
  { start: 619.388, end: 622.480, text: 'The first step consists of scripting the training,' },
  { start: 622.600, end: 626.091, text: 'that is to say, doing blocks of around 20 minutes.' },
  { start: 626.211, end: 629.831, text: 'For example, the course on Aging and Durability of Polymers' },
  { start: 629.951, end: 633.763, text: 'was divided into 27 modules lasting 21 minutes on average.' },
  { start: 633.883, end: 638.342, text: 'We may have modules requiring more time if they are very descriptive.' },
  { start: 638.462, end: 642.541, text: 'Without breaks, the initial lesson is scheduled for 8 hours.' },
  { start: 642.661, end: 647.917, text: 'In its <font color="#FFFF00">inclusive</font> form, the course is 10 hours long.' },
  { start: 648.037, end: 650.540, text: 'Let us remember that the video approach,' },
  { start: 650.660, end: 656.563, text: 'by switching from a course to a video, you need to allow approximately 20% additional time.' },
  { start: 656.683, end: 658.951, text: 'This gives us 27 modules to work on,' },
  { start: 659.071, end: 663.280, text: 'with the help of software <font color="#FFFF00">Subtitle Edit</font>,' },
  { start: 663.400, end: 667.976, text: 'which allows you to obtain <font color="#FFFF00">subtitles</font>. They' },
  { start: 668.096, end: 672.881, text: 'can be translated into the chosen language, according to the final need.' },
  { start: 673.001, end: 680.578, text: 'The last subject that must be addressed for these videos concerns the <font color="#FFFF00">regulations</font> to respect.' },
  { start: 680.698, end: 683.568, text: 'What are the rights and duties to respect?' },
  { start: 683.688, end: 688.133, text: 'The general duties are of course <font color="#FFFF00">copyrights</font>,' },
  { start: 688.253, end: 692.626, text: 'for the courses you use, and also for the illustrative materials.' },
  { start: 692.746, end: 695.752, text: 'Copyright, or failing that the right to quote,' },
  { start: 695.872, end: 698.919, text: 'applies to these documents and their authors.' },
  { start: 699.039, end: 703.221, text: 'If you are filming a teacher, check that you own the image rights,' },
  { start: 703.341, end: 705.977, text: 'and also copyright if they are acting.' },
  { start: 706.097, end: 710.017, text: 'Finally, if you save or use student images, again, you must' },
  { start: 710.137, end: 713.608, text: 'respect <font color="#FFFF00">image rights</font> and check' },
  { start: 713.728, end: 717.775, text: 'that you are compliant with <font color="#FFFF00">GDPR</font>.' },
  { start: 717.895, end: 719.960, text: 'However, when creating videos,' },
  { start: 720.080, end: 723.218, text: 'new rights apply, with particular attention.' },
  { start: 723.338, end: 729.905, text: 'The first, called the <font color="#FFFF00">producer\'s right</font>, is a related right of the producer,' },
  { start: 730.025, end: 733.325, text: 'adapted to videograms, because you have fragmented,' },
  { start: 733.445, end: 735.504, text: 'sequenced and edited a set of video' },
  { start: 735.624, end: 737.907, text: 'elements to produce the montage.' },
  { start: 738.027, end: 741.838, text: 'This is the <font color="#FFFF00">producer\'s right</font>.' },
  { start: 741.958, end: 743.520, text: 'Then there\'s the making,' },
  { start: 743.640, end: 750.158, text: 'and again you have rights to create an <font color="#FFFF00">audiovisual work</font> that need to apply.' },
  { start: 750.278, end: 753.043, text: 'For those who are in the public service and who' },
  { start: 753.163, end: 755.339, text: 'respond to the laws on disability and' },
  { start: 755.459, end: 758.374, text: 'inclusiveness, and who fall under the education' },
  { start: 758.494, end: 761.735, text: 'code, it is provided that, for this public service' },
  { start: 761.855, end: 764.828, text: 'mission, strictly necessary for the inclusion of' },
  { start: 764.948, end: 769.601, text: 'students, all the exploitation rights of the work, produced by an agent of' },
  { start: 769.721, end: 772.860, text: 'the State, necessarily belongs to the State.' },
  { start: 772.980, end: 774.615, text: 'So you are protected.' },
  { start: 774.735, end: 777.708, text: 'If you are not in the public service, if you are' },
  { start: 777.828, end: 780.920, text: 'in a contract school or a non-contract school, you' },
  { start: 781.040, end: 784.440, text: 'must verify that these rights are well established.' },
  { start: 784.560, end: 788.239, text: 'You must make a request to have the rights to use the video,' },
  { start: 788.359, end: 793.733, text: 'that is to say the rights of the producer and the creation of the work, in France.' },
  { start: 793.853, end: 796.414, text: 'And in addition to the other four rights,' },
  { start: 796.534, end: 798.993, text: 'which I mentioned to you initially.' },



  { start: 798.993, end: 8000.000, text: 'Thank you for your attention. Go to Chapter 5.' },

];








const SUBTITLES_ES_CH4 = [

{ start: 1.000, end: 3.978, text: 'Bienvenido al programa BRIDGE -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },

    { start: 3.979, end: 8.162, text: 'Llegamos al cuarto capítulo de esta conferencia.' },
  { start: 8.282, end: 13.996, text: 'Este capítulo trata de la producción de <font color="#FFFF00">vídeos de cursos</font>,' },
  { start: 14.116, end: 21.012, text: 'vídeos <font color="#FFFF00">inclusivos</font>, en la formación impartida a los estudiantes.' },
  { start: 21.132, end: 27.466, text: 'El enfoque del <font color="#FFFF00">video</font> permite responder a varias' },
  { start: 27.586, end: 31.879, text: 'necesidades mencionadas en esta diapositiva, y mencionadas en la parte' },
  { start: 31.999, end: 37.666, text: 'izquierda, y la parte derecha está dedicada a las <font' },
  { start: 37.786, end: 41.816, text: 'color="#FFFF00">discapacidad</font> asociadas o a necesidades no relacionadas con la discapacidad. como ausencias.' },
  { start: 41.936, end: 45.316, text: 'El enfoque del vídeo ofrece varias soluciones,' },
  { start: 45.436, end: 49.152, text: 'la más reconocida es ponerse al día con el curso.' },
  { start: 49.272, end: 53.119, text: 'También te permite revisar el curso varias veces, o' },
  { start: 53.239, end: 57.956, text: 'una parte sólo si aborda un concepto particular.' },
  { start: 58.076, end: 64.322, text: 'El <font color="#FFFF00">vídeo subtitulado</font> también te permite combinar audio y lectura,' },
  { start: 64.442, end: 67.092, text: 'favoreciendo así la memorización.' },
  { start: 67.212, end: 72.126, text: 'También ofrece la posibilidad de seguir el curso sin tomar notas,' },
  { start: 72.246, end: 78.276, text: 'hacer pausas, volver a visualizar las secuencias deseadas.' },
  { start: 78.396, end: 85.026, text: 'Para mí, el valor más importante es el que se menciona al final de esta diapositiva.' },
  { start: 85.146, end: 93.326, text: 'Se trata de la creación de <font color="#FFFF00">subtítulos</font> y <font color="#FFFF00">transcripciones</font>,' },
  { start: 93.446, end: 101.476, text: 'y de la <font color="#FFFF00">descripción oral</font> de lo que se muestra, que también es un punto importante.' },
  { start: 101.596, end: 109.779, text: 'La parte relativa a las <font color="#FFFF00">discapacidades</font> consideradas se muestra a la derecha de esta diapositiva.' },
  { start: 109.899, end: 119.216, text: 'Por supuesto, hay todo lo relacionado con la <font color="#FFFF00">dislexia</font> y los <font color="#FFFF00">trastornos cognitivos</font>.' },
  { start: 119.336, end: 123.366, text: 'gestión de ausencias, cualquiera que sea el motivo.' },
  { start: 123.486, end: 130.202, text: 'También gestiona las dificultades relacionadas con los <font color="#FFFF00">trastornos de la memoria</font>.' },
  { start: 130.322, end: 138.306, text: 'Los vídeos también son muy útiles para los estudiantes que sufren de <font color="#FFFF00">fatiga crónica</font>.' },
  { start: 138.426, end: 143.742, text: 'Pueden pausar el video para continuar cuando estén descansados.' },
  { start: 143.862, end: 151.756, text: 'El enfoque es fundamental para <font color="#FFFF00">problemas de audición</font>, porque' },
  { start: 151.876, end: 157.589, text: 'tener subtítulos, si son adaptables para quienes tienen dificultades visuales, permite' },
  { start: 157.709, end: 165.359, text: 'resolver <font color="#FFFF00">problemas de audición</font> o ver el curso en un ambiente ruidoso.' },
  { start: 165.479, end: 172.506, text: 'Hace unos años, este tipo de <font color="#FFFF00">edición</font>' },
  { start: 172.626, end: 177.672, text: 'era difícil de lograr y había pocas o ninguna solución.' },
  { start: 177.792, end: 181.509, text: 'además de salas especiales con cámaras y cualquier otro medio de grabación.' },
  { start: 181.629, end: 186.976, text: 'Hoy en día esto ya no es así. Hay varios métodos.' },
  { start: 187.096, end: 189.142, text: 'Voy a presentar tres de ellos:' },
  { start: 189.262, end: 195.776, text: 'el más simple se llama enfoque “<font' },
  { start: 195.896, end: 200.009, text: 'color="#FFFF00">Influencer</font>”, que utiliza un smartphone con' },
  { start: 200.129, end: 204.779, text: 'trípode para evitar sacudidas, un micrófono o un micrófono de' },
  { start: 204.899, end: 209.816, text: 'solapa. El profesor graba su lección directamente en una tableta o frente a una proyección de su lección.' },
  { start: 209.936, end: 216.386, text: 'El segundo enfoque es el uso del software <font color="#FFFF00">PowerPoint</font>.' },
  { start: 216.506, end: 217.406, text: '' },
  { start: 217.526, end: 224.332, text: 'Además de PowerPoint, necesitas un micrófono de solapa' },
  { start: 224.452, end: 227.319, text: 'o micrófono para grabar el audio del curso,' },
  { start: 227.439, end: 229.422, text: 'sincronizado con el avance de las diapositivas o vídeos del curso.' },
  { start: 229.542, end: 236.459, text: 'Luego, el software puede exportar las diapositivas con sonido sincronizado al formato de video MP4.' },
  { start: 236.579, end: 241.379, text: 'Encontrarás varios tutoriales en YouTube' },
  { start: 241.499, end: 245.349, text: 'para crear este formato de curso de <font color="#FFFF00">vídeo</font>.' },
  { start: 245.469, end: 251.076, text: 'Finalmente, nuestro tercer método, el que uso' },
  { start: 251.196, end: 257.776, text: 'actualmente, es utilizar un software para reuniones' },
  { start: 257.896, end: 260.409, text: 'remotas: El enfoque “<font' },
  { start: 260.529, end: 264.022, text: 'color="#FFFF00">Reunión</font>” permite la grabación de' },
  { start: 264.142, end: 268.859, text: 'pantalla, grabación de voz y, si lo desea, grabe al orador a través de la cámara de la computadora.' },
  { start: 268.979, end: 275.762, text: 'Este software también le permite realizar la <font color="#FFFF00">transcripción</font> del curso.' },
  { start: 275.882, end: 280.332, text: 'Se transcribirá para su posterior consulta.' },
  { start: 280.452, end: 285.919, text: 'Este método de “Reunión” es un procedimiento interesante para todos los profesores' },
  { start: 286.039, end: 290.556, text: 'que tienen dificultades para dominar el software de edición.' },
  { start: 290.676, end: 294.639, text: 'Al final de la reunión, la edición se puede utilizar.' },
  { start: 294.759, end: 300.006, text: 'No siempre es de gran calidad, pero constituye un primer' },
  { start: 300.126, end: 302.999, text: 'borrador con el vídeo, el audio, las imágenes, que nos' },
  { start: 303.119, end: 309.436, text: 'permiten avanzar en un enfoque de <font color="#FFFF00">inclusividad</font>.' },
  { start: 309.556, end: 313.602, text: 'Sin embargo, hay 4 reglas a seguir para' },
  { start: 313.722, end: 318.106, text: 'que estos vídeos sean realmente <font color="#FFFF00">accesibles</font>.' },
  { start: 318.226, end: 324.676, text: 'El primero es tener un <font color="#FFFF00">sonido</font> claro y perfectamente audible.' },
  { start: 324.796, end: 330.626, text: 'Dicen: <i>“El buen sonido tiene prioridad sobre una buena' },
  { start: 330.746, end: 334.859, text: 'cámara. »</i> Muchas veces, para corregir defectos de' },
  { start: 334.979, end: 336.692, text: 'grabación y mala expresión, es preferible sustituir la' },
  { start: 336.812, end: 344.262, text: 'voz y utilizar una <font color="#FFFF00">voz artificial</font>.' },
  { start: 344.382, end: 349.982, text: 'Estos métodos de “<font color="#FFFF00">Texto a voz</font>” dar' },
  { start: 350.102, end: 355.512, text: 'un 5% de malas transcripciones. Pero por lo demás, la voz es' },
  { start: 355.632, end: 360.796, text: 'mucho más clara, estandarizada y, a veces, mejor que la del hablante.' },
  { start: 360.916, end: 365.829, text: 'Entonces, debemos poner los <font' },
  { start: 365.949, end: 370.262, text: 'color="#FFFF00">subtítulos</font> a disposición de' },
  { start: 370.382, end: 373.566, text: 'personas con problemas de audición, cuyo tamaño debe variar según la necesidad.' },
  { start: 373.686, end: 378.669, text: 'El subtítulo se corrige para ser una versión simplificada del texto.' },
  { start: 378.789, end: 382.836, text: 'No se trata simplemente de una transcripción automática,' },
  { start: 382.956, end: 385.806, text: 'que se puede realizar de forma independiente.' },
  { start: 385.926, end: 390.506, text: 'El subtítulo debe tener buen contraste y el tamaño adecuado' },
  { start: 390.626, end: 394.276, text: 'para personas con problemas de audición.' },
  { start: 394.396, end: 399.796, text: 'El tercer punto es importante y esencial para cursos científicos y técnicos,' },
  { start: 399.916, end: 403.079, text: 'como la química orgánica.' },
  { start: 403.199, end: 407.916, text: 'Necesitamos describir verbalmente lo que es visualmente importante.' },
  { start: 408.036, end: 411.952, text: 'Este es el tercer cuadro en la parte inferior que les presento.' },
  { start: 412.072, end: 419.122, text: 'Esto refuerza el enfoque de <font color="#FFFF00">subtitulado</font> presentado anteriormente.' },
  { start: 419.242, end: 425.909, text: 'El enfoque de <font color="#FFFF00">descripción de' },
  { start: 426.029, end: 427.742, text: 'imagen</font> es esencial en casos como la química orgánica,' },
  { start: 427.862, end: 432.379, text: 'donde hay que tomarse su tiempo para describir una reacción química.' },
  { start: 432.499, end: 435.792, text: 'Los reactivos iniciales, los compuestos obtenidos,' },
  { start: 435.912, end: 441.102, text: 'las condiciones de operación, los catalizadores, los disolventes, etc.' },
  { start: 441.222, end: 442.156, text: 'No podemos conformarnos con una imagen' },
  { start: 442.276, end: 446.189, text: 'del camino de reacción, porque' },
  { start: 446.309, end: 449.092, text: 'inmediatamente perderemos a los estudiantes.' },
  { start: 449.212, end: 450.879, text: 'Todo el proceso químico' },
  { start: 450.999, end: 453.716, text: 'implicado debe describirse oralmente.' },
  { start: 453.836, end: 456.816, text: 'Esto es cierto en muchas ciencias,' },
  { start: 456.936, end: 463.052, text: 'donde es necesario describir clara y oralmente lo que vemos en la pantalla.' },
  { start: 463.172, end: 465.932, text: 'El cuarto punto, en la parte inferior derecha,' },
  { start: 466.052, end: 468.969, text: 'se refiere a la duración de la presentación.' },
  { start: 469.089, end: 475.272, text: 'Es habitual que esta presentación no supere los 25 minutos por concepto importante.' },
  { start: 475.392, end: 480.109, text: 'Podemos ir más allá si se trata de una parte descriptiva.' },
  { start: 480.229, end: 484.972, text: 'De lo contrario, para un concepto importante, 20 minutos es el objetivo.' },
  { start: 485.092, end: 490.339, text: 'Esto evita perder alumnos,' },
  { start: 490.459, end: 496.242, text: 'especialmente aquellos que tienen problemas de memorización o que sufren de <font color="#FFFF00">fatiga cognitiva</font>.' },
  { start: 496.362, end: 502.212, text: 'Ya no es necesario tener un estudio de grabación para tomar clases.' },
  { start: 502.332, end: 507.892, text: 'Sólo necesitas algo de software,' },
  { start: 508.012, end: 513.976, text: 'y el software que he presentado aquí es todo de <font color="#FFFF00">código abierto</font>, con la excepción de PowerPoint.' },
  { start: 514.096, end: 518.409, text: 'Trabajan con múltiples sistemas operativos, como' },
  { start: 518.529, end: 520.826, text: 'Linux, Windows o Mac OS.' },
  { start: 520.946, end: 524.972, text: 'Para grabar, puede usar PowerPoint, combinado' },
  { start: 525.092, end: 530.359, text: 'con <font color="#FFFF00">Edición de' },
  { start: 530.479, end: 532.796, text: 'subtítulos</font> para crear subtítulos y otras funciones.' },
  { start: 532.916, end: 539.522, text: 'Si tienes imágenes, diapositivas, clips de películas o cualquier otro elemento para realizar el curso,' },
  { start: 539.642, end: 548.872, text: 'también puedes grabar el vídeo final con un software llamado <font color="#FFFF00">OBS Studio</font>.' },
  { start: 548.992, end: 554.439, text: 'Este software de código abierto realiza las mismas' },
  { start: 554.559, end: 556.692, text: 'operaciones que el software para reuniones; le' },
  { start: 556.812, end: 559.729, text: 'permite grabar el curso mediante la edición que elija.' },
  { start: 559.849, end: 567.192, text: 'Es necesaria una <font color="#FFFF00">edición</font> para cortar, ensamblar y dividir en capítulos el curso.' },
  { start: 567.312, end: 571.692, text: 'Existen varios programas de edición de código abierto' },
  { start: 571.812, end: 575.572, text: 'para esto, incluido el proporcionado por KDE, Editor' },
  { start: 575.692, end: 579.406, text: 'de vídeo no lineal, conocido como <font' },
  { start: 579.526, end: 582.309, text: 'color="#FFFF00">Kdenlive</font>, que permite editar el vídeo del curso.' },
  { start: 582.429, end: 588.609, text: 'Para la <font color="#FFFF00">transcripción</font> de palabras habladas a texto, una de las' },
  { start: 588.729, end: 595.406, text: 'soluciones reconocidas, sea cual sea el idioma utilizado, es <font color="#FFFF00">Susurro</font>.' },
  { start: 595.526, end: 599.306, text: 'El software que uso en capacitaciones o conferencias es <font' },
  { start: 599.426, end: 607.032, text: 'color="#FFFF00">Subtitle Edit</font>, que es un software eficiente de código' },
  { start: 607.152, end: 614.112, text: 'abierto, compatible con muchos sistemas operativos. y quién hace la transcripción escrita del oral,' },
  { start: 614.232, end: 619.482, text: 'permite la edición y traducción si es necesario.' },
  { start: 619.602, end: 626.299, text: 'Utiliza otro software, como <font color="#FFFF00">Whisper</font> por ejemplo.' },
  { start: 626.419, end: 629.936, text: 'Se encarga de descargarlo automáticamente.' },
  { start: 630.056, end: 634.836, text: 'Si desea traducir del francés a otro idioma,' },
  { start: 634.956, end: 639.072, text: 'existen varios programas de código abierto en Internet.' },
  { start: 639.192, end: 647.002, text: 'Aquí cité <font color="#FFFF00">Argos Translate</font>, pero puede ser cualquier software.' },
  { start: 647.122, end: 652.569, text: 'En cuanto a la limpieza de audio, si quieres continuar con tu voz o' },
  { start: 652.689, end: 659.516, text: 'con sonido no digital, <font color="#FFFF00">Audacity</font> es el' },
  { start: 659.636, end: 663.129, text: 'software para filtrar, reducir el ruido, aumentar el contraste del audio,' },
  { start: 663.249, end: 666.766, text: 'y así tener un notable confort auditivo.' },
  { start: 666.886, end: 672.912, text: 'Por último, tu vídeo debe estar en un formato compatible con la emisión final,' },
  { start: 673.032, end: 675.416, text: 'como MP4 o AVI por ejemplo.' },
  { start: 675.536, end: 678.782, text: 'Necesitas tener un software de conversión de video, y te' },
  { start: 678.902, end: 683.682, text: 'sugiero <font color="#FFFF00">FFmpeg</font>, que te' },
  { start: 683.802, end: 687.919, text: 'permite realizar todas las transformaciones que necesitas.' },
  { start: 688.039, end: 692.732, text: 'Para el enfoque de “Reuniones”, en lugar de OBS Studio, por ejemplo, cito los cuatro principales' },
  { start: 692.852, end: 701.259, text: 'software para reuniones: como <font color="#FFFF00">Zoom</font>, que uso para este formato, <font' },
  { start: 701.379, end: 710.142, text: 'color="#FFFF00">Microsoft Teams</font>, <font color="#FFFF00">WebEx</font> o <font color="#FFFF00">FaceTime</font>.' },
  { start: 710.262, end: 713.379, text: 'Tú eliges el que prefieras.' },
  { start: 713.499, end: 719.082, text: 'Esto es lo que debe hacer en la práctica. Tomé un ejemplo de los sujetos <font' },
  { start: 719.202, end: 726.142, text: 'color="#FFFF00">BRIDGE</font>, cuyo proyecto es dar, en formato digital, formación basada en' },
  { start: 726.262, end: 732.442, text: 'temas de investigación, de ahí el nombre de <i>“Bridging Research and Educación Digital' },
  { start: 732.562, end: 740.456, text: 'Inclusiva”</i>, a los 8 cursos de formación de <font color="#FFFF00">SciencExpert</font>, que son' },
  { start: 740.576, end: 748.869, text: '<font color="#FFFF00">Coloides</font>, <font color="#FFFF00">Envejecimiento y Durabilidad de los' },
  { start: 748.989, end: 756.016, text: 'materiales</font>, <font color="#FFFF00">Introducción a los polímeros</font>, <font color="#FFFF00">Siliconas</font>,' },
  { start: 756.136, end: 763.229, text: '<font color="#FFFF00">Industria de formulación y plásticos</font>, <font color="#FFFF00">Látex</font> y,' },
  { start: 763.349, end: 768.379, text: 'finalmente, <font color="#FFFF00">Pegamentos y adhesivos</font>.' },
  { start: 768.499, end: 772.346, text: 'El primer paso consiste en guionizar la formación,' },
  { start: 772.466, end: 776.249, text: 'es decir, hacer bloques de unos 20 minutos.' },
  { start: 776.369, end: 782.549, text: 'Por ejemplo, el curso sobre Envejecimiento y Durabilidad de Polímeros se' },
  { start: 782.669, end: 787.452, text: 'dividió en 27 módulos con una duración promedio de 21 minutos.' },
  { start: 787.572, end: 792.022, text: 'Es posible que tengamos módulos que requieran más tiempo si son muy descriptivos.' },
  { start: 792.142, end: 796.306, text: 'Sin pausas, la lección inicial está prevista para 8 horas.' },
  { start: 796.426, end: 802.256, text: 'En su forma <font color="#FFFF00">inclusiva</font>, el curso tiene una duración de 10 horas.' },
  { start: 802.376, end: 806.422, text: 'Recordemos que el enfoque del vídeo, Al cambiar de un curso a un' },
  { start: 806.542, end: 811.639, text: 'vídeo, debe dedicar aproximadamente un 20 % de tiempo adicional.' },
  { start: 811.759, end: 814.606, text: 'Esto nos da 27 módulos para trabajar, con la ayuda del' },
  { start: 814.726, end: 820.106, text: 'software. <font color="#FFFF00">Edición de' },
  { start: 820.226, end: 826.076, text: 'subtítulos</font>, que le permite obtener <font' },
  { start: 826.196, end: 829.892, text: 'color="#FFFF00">subtítulos</font>. Se pueden traducir al idioma elegido, según la necesidad final.' },
  { start: 830.012, end: 838.596, text: 'El último tema que hay que abordar para estos vídeos se refiere a las <font color="#FFFF00">reglamentos</font> a respetar.' },
  { start: 838.716, end: 842.499, text: '¿Cuáles son los derechos y deberes a respetar?' },
  { start: 842.619, end: 848.666, text: 'Los deberes generales son, por supuesto, <font color="#FFFF00">derechos de autor</font>,' },
  { start: 848.786, end: 854.416, text: 'para los cursos que utilices, y también para los documentos ilustrativos.' },
  { start: 854.536, end: 859.429, text: 'Los derechos de autor, o en su defecto el derecho de citar,' },
  { start: 859.549, end: 862.066, text: 'se aplican a estos documentos y a sus autores.' },
  { start: 862.186, end: 867.612, text: 'Si estás filmando a un profesor, comprueba que eres el propietario de los derechos de imagen,' },
  { start: 867.732, end: 871.649, text: 'y también de los derechos de autor si está actuando.' },
  { start: 871.769, end: 877.576, text: 'Finalmente, si guardas o utilizas imágenes de estudiantes,' },
  { start: 877.696, end: 882.429, text: 'nuevamente, debes respetar los <font color="#FFFF00">derechos de' },
  { start: 882.549, end: 887.599, text: 'imagen</font> y verificar que cumples con el <font color="#FFFF00">GDPR</font>.' },
  { start: 887.719, end: 890.546, text: 'Sin embargo, al crear vídeos,' },
  { start: 890.666, end: 895.629, text: 'se aplican nuevos derechos, con especial atención.' },
  { start: 895.749, end: 902.642, text: 'El primero, denominado <font color="#FFFF00">derecho del' },
  { start: 902.762, end: 907.969, text: 'productor</font>, es un derecho conexo del productor,' },
  { start: 908.089, end: 910.756, text: 'adaptado a los videogramas, porque has fragmentado,' },
  { start: 910.876, end: 913.392, text: 'secuenciado y editado un conjunto de elementos de vídeo para lograr el montaje.' },
  { start: 913.512, end: 918.229, text: 'Este es el <font color="#FFFF00">derecho del productor</font>.' },
  { start: 918.349, end: 922.376, text: 'Luego está la creación,' },
  { start: 922.496, end: 930.079, text: 'y nuevamente tienes derechos para crear una <font color="#FFFF00">obra audiovisual</font> que debes aplicar.' },
  { start: 930.199, end: 934.066, text: 'Para aquellos que están en el servicio público y' },
  { start: 934.186, end: 937.166, text: 'que cumplen con las leyes sobre discapacidad e' },
  { start: 937.286, end: 940.066, text: 'inclusión, y que están sujetos al código de educación,' },
  { start: 940.186, end: 944.212, text: 'está previsto que, para esta misión de servicio público,' },
  { start: 944.332, end: 949.379, text: 'estrictamente necesario para la inclusión de los estudiantes,' },
  { start: 949.499, end: 953.079, text: 'se pierdan todos los derechos de explotación de la' },
  { start: 953.199, end: 956.762, text: 'obra, producida por un agente del Estado, pertenece necesariamente al Estado.' },
  { start: 956.882, end: 958.932, text: 'Entonces estás protegido.' },
  { start: 959.052, end: 964.766, text: 'Si no estás en el servicio público, si estás en una' },
  { start: 964.886, end: 968.132, text: 'escuela por contrato o en una escuela sin' },
  { start: 968.252, end: 970.902, text: 'contrato, debe verificar que estos derechos estén bien establecidos.' },
  { start: 971.022, end: 976.536, text: 'Debes realizar una solicitud para tener los derechos de uso del vídeo,' },
  { start: 976.656, end: 982.352, text: 'es decir los derechos del productor y de creación de la obra, en Francia.' },
  { start: 982.472, end: 985.052, text: 'Y además de los otros cuatro derechos,' },
  { start: 985.172, end: 988.222, text: 'que os mencioné inicialmente.' },


  { start: 988.223, end:9000.000, text: 'Gracias por su atención. Vaya al capítulo 5.' },

];




const SUBTITLES_IT_CH4 = [
{ start: 1.000, end: 3.978, text: 'Benvenuti nel programma BRIDGE -<font color="#FFFF00"> Bridging Research and Inclusive Digital Education</font>' },

   { start: 3.979, end: 7.629, text: 'Arriviamo al quarto capitolo di questo convegno.' },
  { start: 7.749, end: 13.729, text: 'Questo capitolo riguarda la produzione di <font color="#FFFF00">video dei corsi</font>,' },
  { start: 13.849, end: 20.279, text: 'video <font color="#FFFF00">inclusivi</font>, nella formazione impartita agli studenti.' },
  { start: 20.399, end: 24.999, text: 'L\'approccio <font color="#FFFF00">video</font> consente di rispondere' },
  { start: 25.119, end: 29.719, text: 'a diversi bisogni menzionati in questa diapositiva e menzionati nella' },
  { start: 29.839, end: 33.686, text: 'parte sinistra, e la parte destra è dedicata alle <font' },
  { start: 33.806, end: 40.036, text: 'color="#FFFF00">disabilità</font> associate o ai bisogni non-disabili, come assenze.' },
  { start: 40.156, end: 43.136, text: 'L\'approccio video offre diverse soluzioni,' },
  { start: 43.256, end: 48.972, text: 'la più riconosciuta delle quali è quella di recuperare il ritardo sul percorso.' },
  { start: 49.092, end: 52.806, text: 'Permette anche di rivedere il corso più volte, oppure' },
  { start: 52.926, end: 56.776, text: 'una parte solo se affronta un concetto particolare.' },
  { start: 56.896, end: 63.609, text: 'Il <font color="#FFFF00">video sottotitolato</font> consente inoltre di combinare audio e lettura,' },
  { start: 63.729, end: 66.379, text: 'favorendo così la memorizzazione.' },
  { start: 66.499, end: 71.479, text: 'Offre inoltre la possibilità di seguire il corso senza prendere appunti,' },
  { start: 71.599, end: 77.429, text: 'di fare delle pause, di tornare indietro per visionare le sequenze desiderate.' },
  { start: 77.549, end: 83.712, text: 'Per me, il valore più importante è quello menzionato in fondo a questa diapositiva.' },
  { start: 83.832, end: 91.366, text: 'Ciò riguarda la creazione di <font color="#FFFF00">sottotitoli</font> e <font color="#FFFF00">trascrizioni</font>' },
  { start: 91.486, end: 99.516, text: 'e la <font color="#FFFF00">descrizione orale</font> di ciò che viene mostrato, che è anche un punto importante.' },
  { start: 99.636, end: 107.752, text: 'La parte relativa alle <font color="#FFFF00">disabilità</font> considerate è visualizzata a destra di questa slide.' },
  { start: 107.872, end: 117.256, text: 'Naturalmente c\'è tutto ciò che riguarda la <font color="#FFFF00">dislessia</font> e i <font color="#FFFF00">disturbi cognitivi</font>.' },
  { start: 117.376, end: 121.206, text: 'Gestione delle assenze, qualunque sia il motivo.' },
  { start: 121.326, end: 127.842, text: 'Gestisce anche le difficoltà legate ai <font color="#FFFF00">disturbi della memoria</font>.' },
  { start: 127.962, end: 135.879, text: 'I video sono molto utili anche per gli studenti che soffrono di <font color="#FFFF00">stanchezza cronica</font>.' },
  { start: 135.999, end: 140.782, text: 'Possono mettere in pausa il video per continuare quando riposano.' },
  { start: 140.902, end: 146.882, text: 'L\'approccio è fondamentale per i <font color="#FFFF00">problemi di udito</font>, perché' },
  { start: 147.002, end: 152.962, text: 'avere i sottotitoli, se adattabili a chi ha difficoltà visive, permette di risolvere' },
  { start: 153.082, end: 159.466, text: '<font color="#FFFF00">problemi di udito</font> o vedere il corso in un ambiente rumoroso.' },
  { start: 159.586, end: 164.566, text: 'Alcuni anni fa, questo tipo di <font color="#FFFF00">modifica</font> era' },
  { start: 164.686, end: 169.402, text: 'difficile da realizzare e le soluzioni erano poche o nessuna. ad' },
  { start: 169.522, end: 175.639, text: 'eccezione di stanze speciali con telecamere e qualsiasi altro mezzo di registrazione.' },
  { start: 175.759, end: 179.659, text: 'Oggi non è più così. Esistono diversi metodi.' },
  { start: 179.779, end: 181.159, text: 'Ne presenterò tre:' },
  { start: 181.279, end: 184.146, text: 'il più semplice è chiamato approccio “<font' },
  { start: 184.266, end: 189.112, text: 'color="#FFFF00">Influencer</font>”, che utilizza uno smartphone con un' },
  { start: 189.232, end: 193.279, text: 'treppiede per evitare tremori, un microfono o un microfono' },
  { start: 193.399, end: 202.232, text: 'lavalier. L\'insegnante registra la sua lezione direttamente su un tablet o davanti ad una proiezione della sua lezione.' },
  { start: 202.352, end: 208.269, text: 'Il secondo approccio è l\'uso del software <font color="#FFFF00">PowerPoint</font>.' },
  { start: 208.389, end: 209.289, text: '' },
  { start: 209.409, end: 213.322, text: 'Oltre a PowerPoint, è necessario un microfono lavalier o' },
  { start: 213.442, end: 216.689, text: 'un microfono per registrare l\'audio del corso,' },
  { start: 216.809, end: 221.526, text: 'sincronizzato con l\'andamento delle slide o dei video del corso.' },
  { start: 221.646, end: 228.496, text: 'Il software può quindi esportare le diapositive sincronizzate con l\'audio nel formato video MP4.' },
  { start: 228.616, end: 231.282, text: 'Troverai diversi tutorial su YouTube per' },
  { start: 231.402, end: 236.519, text: 'realizzare questo formato di corso <font color="#FFFF00">video</font>.' },
  { start: 236.639, end: 240.399, text: 'Infine, il nostro terzo metodo, quello che utilizzo' },
  { start: 240.519, end: 244.832, text: 'attualmente, consiste nell\'utilizzare un software per riunioni' },
  { start: 244.952, end: 249.066, text: 'remote: L\'approccio "<font color="#FFFF00">Riunione</font>"' },
  { start: 249.186, end: 253.166, text: 'consente la registrazione dello schermo, la registrazione' },
  { start: 253.286, end: 259.629, text: 'vocale e, se lo desideri, registra l\'oratore attraverso la fotocamera del computer.' },
  { start: 259.749, end: 266.799, text: 'Questi software ti permettono anche di fare la <font color="#FFFF00">trascrizione</font> del corso.' },
  { start: 266.919, end: 271.436, text: 'Verrà trascritto per poter essere consultato successivamente.' },
  { start: 271.556, end: 275.956, text: 'Questo metodo “Meeting” è una procedura interessante per tutti gli' },
  { start: 276.076, end: 281.192, text: 'insegnanti che hanno difficoltà a padroneggiare i software di editing.' },
  { start: 281.312, end: 285.296, text: 'Al termine della riunione la modifica è utilizzabile.' },
  { start: 285.416, end: 289.596, text: 'Non è sempre di alta qualità, ma costituisce una prima bozza' },
  { start: 289.716, end: 293.989, text: 'con il video, l\'audio, le immagini, che ci permettono di' },
  { start: 294.109, end: 299.359, text: 'portare avanti un approccio di <font color="#FFFF00">inclusività</font>.' },
  { start: 299.479, end: 302.212, text: 'Ci sono però 4 regole da seguire affinché' },
  { start: 302.332, end: 307.449, text: 'questi video siano veramente <font color="#FFFF00">accessibili</font>.' },
  { start: 307.569, end: 313.752, text: 'Il primo è avere un <font color="#FFFF00">suono</font> chiaro e perfettamente udibile.' },
  { start: 313.872, end: 318.186, text: 'Dicono: <i>“Un buon suono ha la priorità su una buona macchina' },
  { start: 318.306, end: 322.802, text: 'fotografica. »</i> Molto spesso, per correggere difetti di' },
  { start: 322.922, end: 327.302, text: 'registrazione e scarsa espressione, è preferibile sostituire la' },
  { start: 327.422, end: 332.939, text: 'propria voce e utilizzare una <font color="#FFFF00">voce artificiale</font>.' },
  { start: 333.059, end: 337.842, text: 'Questi metodi "<font color="#FFFF00">Testo in voce</font>". danno' },
  { start: 337.962, end: 342.992, text: 'il 5% di trascrizioni errate. Ma per il resto, la voce è molto più' },
  { start: 343.112, end: 348.142, text: 'chiara, standardizzata e talvolta migliore di quella di chi parla.' },
  { start: 348.262, end: 350.929, text: 'Poi dobbiamo rendere disponibili i <font' },
  { start: 351.049, end: 354.449, text: 'color="#FFFF00">sottotitoli</font> alle persone con' },
  { start: 354.569, end: 360.532, text: 'problemi di udito, le cui dimensioni dovranno variare a seconda della necessità.' },
  { start: 360.652, end: 366.236, text: 'Il sottotitolo viene corretto per essere una versione semplificata del testo.' },
  { start: 366.356, end: 370.469, text: 'Non si tratta semplicemente di una trascrizione automatica,' },
  { start: 370.589, end: 373.639, text: 'che può essere effettuata in autonomia.' },
  { start: 373.759, end: 377.226, text: 'Il sottotitolo dovrebbe avere un buon contrasto e la' },
  { start: 377.346, end: 381.462, text: 'dimensione giusta per le persone con problemi di udito.' },
  { start: 381.582, end: 386.829, text: 'Il terzo punto è importante ed essenziale per i corsi scientifici e tecnici,' },
  { start: 386.949, end: 389.799, text: 'come ad esempio la chimica organica.' },
  { start: 389.919, end: 394.702, text: 'Dobbiamo descrivere verbalmente ciò che è visivamente importante.' },
  { start: 394.822, end: 398.672, text: 'Questa è la terza casella in basso che ti presento.' },
  { start: 398.792, end: 405.842, text: 'Ciò rafforza l\'approccio al <font color="#FFFF00">sottotitolazione</font> presentato in precedenza.' },
  { start: 405.962, end: 408.962, text: 'L\'approccio <font color="#FFFF00">descrizione' },
  { start: 409.082, end: 412.882, text: 'dell\'immagine</font> è essenziale in casi come la chimica' },
  { start: 413.002, end: 419.632, text: 'organica, in cui devi prenderti il ​​tempo necessario per descrivere una reazione chimica.' },
  { start: 419.752, end: 422.846, text: 'I reagenti iniziali, i composti ottenuti,' },
  { start: 422.966, end: 427.822, text: 'le condizioni operative, i catalizzatori, i solventi, ecc.' },
  { start: 427.942, end: 429.876, text: 'Non possiamo accontentarci di' },
  { start: 429.996, end: 432.642, text: 'un’immagine del percorso di reazione,' },
  { start: 432.762, end: 436.212, text: 'perché perderemo immediatamente gli studenti.' },
  { start: 436.332, end: 438.666, text: 'L\'intero processo chimico coinvolto' },
  { start: 438.786, end: 441.369, text: 'deve essere descritto oralmente.' },
  { start: 441.489, end: 443.736, text: 'Questo è vero in molte scienze,' },
  { start: 443.856, end: 449.772, text: 'dove è necessario descrivere in modo chiaro e orale ciò che vediamo sullo schermo.' },
  { start: 449.892, end: 452.586, text: 'Il quarto punto, in basso a destra,' },
  { start: 452.706, end: 455.756, text: 'riguarda la durata della presentazione.' },
  { start: 455.876, end: 462.126, text: 'È consuetudine che questa presentazione non superi i 25 minuti per concetto importante.' },
  { start: 462.246, end: 465.962, text: 'Possiamo andare oltre se è una parte descrittiva.' },
  { start: 466.082, end: 471.159, text: 'Altrimenti, per un concetto importante, 20 minuti è l\'obiettivo.' },
  { start: 471.279, end: 474.392, text: 'In questo modo si evita di perdere studenti,' },
  { start: 474.512, end: 483.429, text: 'soprattutto quelli che hanno problemi di memorizzazione o che soffrono di <font color="#FFFF00">affaticamento cognitivo</font>.' },
  { start: 483.549, end: 489.199, text: 'Non è più necessario avere uno studio di registrazione per seguire le lezioni.' },
  { start: 489.319, end: 494.186, text: 'Hai solo bisogno di un po\' di software e i software che ho presentato qui' },
  { start: 494.306, end: 500.269, text: 'sono tutti <font color="#FFFF00">open source</font>, ad eccezione di PowerPoint.' },
  { start: 500.389, end: 503.369, text: 'Funzionano con più sistemi operativi, come' },
  { start: 503.489, end: 505.652, text: 'Linux, Windows o MacOS.' },
  { start: 505.772, end: 509.399, text: 'Per la registrazione, puoi utilizzare PowerPoint,' },
  { start: 509.519, end: 512.452, text: 'combinato con <font color="#FFFF00">Modifica' },
  { start: 512.572, end: 517.222, text: 'sottotitoli</font> per creare sottotitoli e altre funzionalità.' },
  { start: 517.342, end: 523.816, text: 'Se hai immagini, diapositive, filmati o qualsiasi altro elemento per realizzare il corso,' },
  { start: 523.936, end: 531.252, text: 'puoi anche registrare il video finale con il software chiamato <font color="#FFFF00">OBS Studio</font>.' },
  { start: 531.372, end: 534.306, text: 'Questo software open source esegue le stesse' },
  { start: 534.426, end: 538.072, text: 'operazioni del software per riunioni, ti consente di' },
  { start: 538.192, end: 542.509, text: 'registrare il corso utilizzando una modifica a tua scelta.' },
  { start: 542.629, end: 550.392, text: 'Il <font color="#FFFF00">modifica</font> è necessario per tagliare, assemblare e creare capitoli del corso.' },
  { start: 550.512, end: 553.979, text: 'Esistono diversi software di editing open source per' },
  { start: 554.099, end: 557.859, text: 'questo, incluso quello fornito da KDE, Editor video' },
  { start: 557.979, end: 560.026, text: 'non lineare, noto come <font' },
  { start: 560.146, end: 566.242, text: 'color="#FFFF00">Kdenlive</font>, che ti consente di modificare il video del corso.' },
  { start: 566.362, end: 573.656, text: 'Per la <font color="#FFFF00">trascrizione</font> del parlato in testo, una delle soluzioni riconosciute,' },
  { start: 573.776, end: 579.472, text: 'qualunque sia la lingua utilizzata, è <font color="#FFFF00">Sussurro</font>.' },
  { start: 579.592, end: 584.526, text: 'Il software che utilizzo durante la formazione o per le conferenze è <font' },
  { start: 584.646, end: 590.272, text: 'color="#FFFF00">Subtitle Edit</font>, che è un efficiente software open source,' },
  { start: 590.392, end: 596.819, text: 'compatibile con molti sistemi operativi, e chi effettua la trascrizione scritta dell\'orale,' },
  { start: 596.939, end: 601.036, text: 'consente la modifica e la traduzione, se necessario.' },
  { start: 601.156, end: 607.052, text: 'Utilizza altri software, come <font color="#FFFF00">Whisper</font> per esempio.' },
  { start: 607.172, end: 610.289, text: 'Si occupa di scaricarlo automaticamente.' },
  { start: 610.409, end: 613.856, text: 'Se vuoi tradurre dal francese in un\'altra lingua,' },
  { start: 613.976, end: 618.292, text: 'su Internet sono disponibili diversi software open source.' },
  { start: 618.412, end: 625.242, text: 'Qui ho citato <font color="#FFFF00">Argos Translate</font>, ma può essere qualsiasi software.' },
  { start: 625.362, end: 630.342, text: 'Per quanto riguarda la pulizia dell\'audio, se vuoi continuare con la tua' },
  { start: 630.462, end: 635.509, text: 'voce o con audio non digitale, <font color="#FFFF00">Audacity</font> è il' },
  { start: 635.629, end: 640.902, text: 'software per filtrare, ridurre il rumore, aumentare il contrasto audio,' },
  { start: 641.022, end: 644.339, text: 'e quindi avere un notevole comfort uditivo.' },
  { start: 644.459, end: 650.952, text: 'Infine, il tuo video deve essere messo in un formato compatibile con la trasmissione finale,' },
  { start: 651.072, end: 653.256, text: 'come ad esempio MP4 o AVI.' },
  { start: 653.376, end: 657.309, text: 'È necessario disporre di un software di conversione video e' },
  { start: 657.429, end: 661.209, text: 'suggerisco <font color="#FFFF00">FFmpeg</font>, che ti' },
  { start: 661.329, end: 666.046, text: 'consente di eseguire tutte le trasformazioni di cui hai bisogno.' },
  { start: 666.166, end: 673.192, text: 'Per l’approccio “Meeting”, al posto di OBS Studio ad esempio, cito i quattro principali software per' },
  { start: 673.312, end: 679.652, text: 'meeting, come <font color="#FFFF00">Zoom</font>, che utilizzo per questo formato, <font' },
  { start: 679.772, end: 688.069, text: 'color="#FFFF00">Microsoft Teams</font>, <font color="#FFFF00">WebEx</font> o <font color="#FFFF00">FaceTime</font>.' },
  { start: 688.189, end: 690.572, text: 'Scegli quello che preferisci.' },
  { start: 690.692, end: 695.609, text: 'Ecco cosa fare praticamente. Ho preso un esempio dai soggetti <font' },
  { start: 695.729, end: 701.802, text: 'color="#FFFF00">BRIDGE</font>, il cui progetto è quello di dare, in forma digitale,' },
  { start: 701.922, end: 707.769, text: 'formazione basata su temi di ricerca, da qui il nome di <i>“Bridging Research and</i>' },
  { start: 707.889, end: 712.869, text: '<i>Inclusive Digital Education”</i>, sugli 8 percorsi formativi di <font' },
  { start: 712.989, end: 719.349, text: 'color="#FFFF00">SciencExpert</font>, che sono <font color="#FFFF00">Colloidi</font>, <font' },
  { start: 719.469, end: 730.609, text: 'color="#FFFF00">Invecchiamento e Durabilità dei materiali</font>, <font color="#FFFF00">Introduzione ai polimeri</font>, <font color="#FFFF00">Siliconi</font>,' },
  { start: 730.729, end: 738.756, text: '<font color="#FFFF00">Industria della formulazione e della plastica</font>, <font color="#FFFF00">Lattice</font> e,' },
  { start: 738.876, end: 743.039, text: 'infine, <font color="#FFFF00">Colle e adesivi</font>.' },
  { start: 743.159, end: 746.939, text: 'Il primo passo consiste nello scriptare l\'allenamento,' },
  { start: 747.059, end: 750.576, text: 'cioè nell\'eseguire blocchi di circa 20 minuti.' },
  { start: 750.696, end: 755.276, text: 'Ad esempio, il corso su Invecchiamento e Durabilità dei Polimeri è' },
  { start: 755.396, end: 759.912, text: 'stato suddiviso in 27 moduli della durata media di 21 minuti.' },
  { start: 760.032, end: 765.349, text: 'Potremmo avere moduli che richiedono più tempo se sono molto descrittivi.' },
  { start: 765.469, end: 769.699, text: 'Senza pause, la lezione iniziale è prevista per 8 ore.' },
  { start: 769.819, end: 775.582, text: 'Nella sua forma <font color="#FFFF00">inclusiva</font>, il corso dura 10 ore.' },
  { start: 775.702, end: 778.082, text: 'Ricordiamo che l\'approccio video,' },
  { start: 778.202, end: 784.252, text: 'passando da un corso a un video è necessario concedere circa il 20% di tempo in più.' },
  { start: 784.372, end: 788.219, text: 'Questo ci dà 27 moduli su cui lavorare, con l\'aiuto del' },
  { start: 788.339, end: 792.919, text: 'software <font color="#FFFF00">Modifica sottotitoli</font>, che ti' },
  { start: 793.039, end: 794.772, text: 'consente di ottenere <font' },
  { start: 794.892, end: 803.772, text: 'color="#FFFF00">sottotitoli</font>. Possono essere tradotti nella lingua prescelta, a seconda della necessità finale.' },
  { start: 803.892, end: 812.009, text: 'L\'ultimo tema che bisogna affrontare per questi video riguarda le <font color="#FFFF00">norme</font> da rispettare.' },
  { start: 812.129, end: 815.646, text: 'Quali sono i diritti e i doveri da rispettare?' },
  { start: 815.766, end: 820.946, text: 'I doveri generali sono ovviamente i <font color="#FFFF00">copyright</font>,' },
  { start: 821.066, end: 825.896, text: 'per i corsi che utilizzi, e anche per i documenti illustrativi.' },
  { start: 826.016, end: 831.222, text: 'Il diritto d\'autore o, in mancanza di questo, il diritto di citazione,' },
  { start: 831.342, end: 834.926, text: 'si applica a questi documenti e ai loro autori.' },
  { start: 835.046, end: 837.292, text: 'Se stai filmando un insegnante,' },
  { start: 837.412, end: 843.729, text: 'controlla di possedere i diritti d\'immagine e anche i diritti d\'autore se sta recitando.' },
  { start: 843.849, end: 848.409, text: 'Infine, se salvi o utilizzi immagini degli studenti, ancora una' },
  { start: 848.529, end: 852.309, text: 'volta, devi rispettare i <font color="#FFFF00">diritti' },
  { start: 852.429, end: 858.879, text: 'sull\'immagine</font> e verificare di essere conforme al <font color="#FFFF00">GDPR</font>.' },
  { start: 858.999, end: 861.559, text: 'Tuttavia, quando si creano video,' },
  { start: 861.679, end: 865.976, text: 'si applicano nuovi diritti, con particolare attenzione.' },
  { start: 866.096, end: 869.742, text: 'Il primo, chiamato <font color="#FFFF00">diritto del' },
  { start: 869.862, end: 873.956, text: 'produttore</font>, è un diritto connesso del produttore,' },
  { start: 874.076, end: 877.636, text: 'adattato ai videogrammi, perché hai frammentato,' },
  { start: 877.756, end: 883.472, text: 'sequenziato e modificato una serie di elementi video per ottenere il montaggio.' },
  { start: 883.592, end: 888.309, text: 'Questo è il <font color="#FFFF00">diritto del produttore</font>.' },
  { start: 888.429, end: 891.789, text: 'Poi c\'è la realizzazione e, ancora una volta,' },
  { start: 891.909, end: 899.159, text: 'hai i diritti per creare un\'<font color="#FFFF00">opera audiovisiva</font> che deve essere presentata.' },
  { start: 899.279, end: 902.412, text: 'Per coloro che sono nel servizio pubblico e che' },
  { start: 902.532, end: 905.066, text: 'soddisfano le leggi sulla disabilità e' },
  { start: 905.186, end: 909.299, text: 'sull\'inclusione e che rientrano nel codice dell\'istruzione,' },
  { start: 909.419, end: 913.579, text: 'è previsto che, per questa missione di servizio pubblico,' },
  { start: 913.699, end: 917.612, text: 'strettamente necessaria per l\'inclusione degli studenti,' },
  { start: 917.732, end: 921.579, text: 'tutti i diritti di sfruttamento dell\'opera, prodotto da' },
  { start: 921.699, end: 926.396, text: 'un agente dello Stato, appartiene necessariamente allo Stato.' },
  { start: 926.516, end: 928.299, text: 'Quindi sei protetto.' },
  { start: 928.419, end: 931.932, text: 'Se non sei nel servizio pubblico, se frequenti una' },
  { start: 932.052, end: 935.566, text: 'scuola a contratto o una scuola non a contratto, è' },
  { start: 935.686, end: 940.202, text: 'necessario verificare che tali diritti siano ben consolidati.' },
  { start: 940.322, end: 945.636, text: 'È necessario fare una richiesta per ottenere i diritti di utilizzo del video,' },
  { start: 945.756, end: 950.852, text: 'cioè i diritti di produttore e di creazione dell\'opera, in Francia.' },
  { start: 950.972, end: 953.886, text: 'E in aggiunta agli altri quattro diritti,' },
  { start: 954.006, end: 956.722, text: 'di cui ti ho parlato inizialmente.' },


  { start: 956.722, end: 960.000, text: 'Grazie per la vostra attenzione. Andate al capitolo 3.' },
];


